int already = FUZZ_GET_ATTR_INT_GLOBAL("hilti_inited");
if (already) { FUZZ_BAIL(); }

// Call the target function.
hilti::rt::init();

// Validate: runtime should report initialized now.
bool inited = hilti::rt::isInitialized();
FUZZ_ASSERT(inited, "hilti::rt::init should result in isInitialized()==true");

// Track global state for other stubs.
FUZZ_SET_ATTR_INT_GLOBAL("hilti_inited", 1);

// Validation: Ensures init is only called once and asserts post-condition via isInitialized().

// Must only shut down if previously initialized.
int already = FUZZ_GET_ATTR_INT_GLOBAL("hilti_inited");
if (!already) { FUZZ_BAIL(); }

hilti::rt::done();

// After shutdown, library should not be initialized anymore.
bool inited = hilti::rt::isInitialized();
FUZZ_ASSERT(!inited, "hilti::rt::done should result in isInitialized()==false");

// Update global state.
FUZZ_SET_ATTR_INT_GLOBAL("hilti_inited", 0);

// Validation: Guards correct lifecycle ordering and checks post-condition.

