// Cross-check against tracked global (best-effort). If mismatch occurs, our sequencing is broken.
int tracked = FUZZ_GET_ATTR_INT_GLOBAL("hilti_inited");
if ((tracked != 0) != inited) {
    FUZZ_BAIL();
}

