m.name = "fuzz_mod";

// Provide a random id.
m.id = *FUZZ_PARAM(uint64_t);

// Randomly choose to set callbacks or leave them null; use captureless lambdas convertible to function pointers.
unsigned int r = *FUZZ_PARAM(unsigned int);
